from datetime import UTC, date, datetime, timedelta

import pytest_httpx

from snowfall.vendor.junction_one.client import JunctionOneClient
from snowfall.vendor.junction_one.conftest import load_file_fixture
from snowfall.vendor.junction_one.models import autogenerated as auto_models
from snowfall.vendor.junction_one.models import base as models


async def test_create_trip(
    junction_one_client: JunctionOneClient,
    httpx_mock: pytest_httpx.HTTPXMock,
) -> None:
    fixture = await load_file_fixture("POST-v1-trip-create.json")

    httpx_mock.add_response(
        method="POST",
        url="https://localhost/v1/trip/create",
        status_code=http.HTTPStatus.OK.value,
        json=fixture,
    )

    trip = await junction_one_client.create_trip(
        models.TripCreateRequest(
            name="bla",
            start_date=date(2025, 10, 10),
            end_date=date(2025, 10, 12),
            org_id=635604,
            booker_ids=[2602533],
        ),
    )

    assert trip == auto_models.Trip(**fixture["data"]["trip"])


