async def test_add_fop_to_tripboard(
    junction_one_client: JunctionOneClient,
    httpx_mock: pytest_httpx.HTTPXMock,
) -> None:
    httpx_mock.add_response(
        method="POST",
        url="https://localhost/v1/tripboard/addFop",
        status_code=http.HTTPStatus.OK.value,
        json=await load_file_fixture("POST-v1-add-fop.json"),
    )

    tripboard_id = 2623172
    card_id = 854

    response = await junction_one_client.add_fop(
        models.AddFopRequest(
            tripboard_ref_id=tripboard_id,
            card_id=card_id,
        ),
    )

    boards = response.boards
    assert boards, "No boards found in the response"

    first_board = boards[0]
    refs = first_board.refs
    assert refs, "No refs found in the first board"

    tripboard_from_response = refs[0]
    tripboard_response_ref_id = tripboard_from_response.id
    assert tripboard_id == tripboard_response_ref_id, "Tripboard IDs do not match"

    fops = tripboard_from_response.fops
    assert fops, "No fops found in tripboard_from_response"

    fop_card_ids = {fop.card_id for fop in fops}
    assert card_id in fop_card_ids, "Card ID {0} not found in fops".format(card_id)


async def test_process_tripboard(
    junction_one_client: JunctionOneClient,
    httpx_mock: pytest_httpx.HTTPXMock,
) -> None:
    fixture = await load_file_fixture("POST-v1-tripboard-process.json")

    httpx_mock.add_response(
        method="POST",
        url="https://localhost/v1/tripboard/process",
        status_code=http.HTTPStatus.OK.value,
        json=fixture,
    )

    tripboard_id = 2623403
    flag = auto_models.TripBoardProcessingFlags.commit

    response = await junction_one_client.process_tripboard(
        models.TripboardProcessRequest(
            id=tripboard_id,
            flag=flag,
        ),
    )

    assert response == auto_models.GetTripBoardsResponse(**fixture["data"])
